/**
 * Theme table, generated files and checks (docs/LAYOUT-THEME-PLAN.md §4 and §6; phase T4).
 *
 *   npx tsx scripts/site/theme.ts           → checks + the 14-theme summary
 *   npx tsx scripts/site/theme.ts --write   → regenerate src/site/theme/{table.ts,dots.ts,themes.css}, the boot
 *                                             script in index.html and its CSP hash in vercel.json, then check
 *   npx tsx scripts/site/theme.ts --check   → checks only (exit 1 on a failure; the files must be current)
 *
 * Role names are the CSS custom properties of src/tokens.css (`red` = {colors.dotActive}, `surface`, `value`, …).
 * Checks, per theme (7 accents × dark/light): every generated colour inside sRGB; WCAG 4.5:1 for the text roles
 * (`value`, `label`, `mute`) and `red-text` on every surface (+ APCA Lc 60 on `surface`), `on-red` on the solid,
 * `red-surface-text` on `red-surface`; 3:1 for the accent dots (`red`) and `red-line` on `surface` and `bg`; APCA
 * order of the dot tones (faint < mid < idle < value, red-dim < red); the accent distinct from `value`
 * and the greys (`dot-idle`, `dot-mid`) under normal vision and simulated protanopia, deuteranopia and
 * tritanopia; `dark_signal` equal to src/tokens.css `:root` (today's colours) and `dot480`; `vite` equal to its
 * pins; the boot script ≡ the store's resolution (attributes, `color-scheme`, `theme-color`); `tokensOf()`;
 * the generated files and the CSP hash current.
 * Called from verify.ts (`themeChecks(assert)`); runnable alone.
 */
import { createHash } from 'node:crypto'
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { ACCENT_ROLES, ACCENT_SPECS, DARK, DOT_ROLES, generateAll, NEUTRAL_ROLES, NEUTRALS, neutralRoles, PINS, type Role, type Theme } from '../../src/site/theme/accents'
import { apca, CVD_DE, CVD_DL, distinctness, gamutMisses, hexToRgb, wcag } from '../../src/site/theme/color'
import { BOOT_END, BOOT_SCRIPT, BOOT_START, bootTag } from '../../src/site/theme/boot'
import { ACCENTS, SCHEMES, type Scheme, type ThemeName } from '../../src/site/theme/names'
import type { ThemeTokens } from '../../src/engine/types'
import { dot480 } from '../../src/engine/theme/tokens'

type Assert = (name: string, cond: boolean, detail?: string) => void

const FILES = { tokens: 'src/tokens.css', table: 'src/site/theme/table.ts', dots: 'src/site/theme/dots.ts', css: 'src/site/theme/themes.css', html: 'index.html', vercel: 'vercel.json', dist: 'dist/index.html' }
const GEN = 'Generated by `npx tsx scripts/site/theme.ts --write` from src/site/theme/accents.ts: do not edit.'

/**
 * Today's colours: the colour roles of the first `:root` block of src/tokens.css (T0's single token block, also
 * the no-theme fallback of the essay and legal pages). `dark_signal` must equal every one of them.
 */
function todayRoles(): Partial<Record<Role, string>> {
  const css = readFileSync(FILES.tokens, 'utf8').replace(/\/\*[\s\S]*?\*\//g, ''), root = /:root\s*\{([^}]*)\}/.exec(css)?.[1] ?? ''
  // every custom property holding a colour literal is a colour role (so a role the generator doesn't know fails the check)
  const out: Partial<Record<Role, string>> = {}
  for (const m of root.matchAll(/--([\w-]+)\s*:\s*(#[0-9a-f]{3,8}|rgba?\([^)]*\))\s*;/gi)) out[m[1] as Role] = m[2].trim()
  return out
}
/**
 * Today's values that fail a rule, kept on `dark_signal` only (lifted in T6, "all text ≥ 4.5:1"):
 * the mute grey is 3.8:1 on the card surface, and white on the signal red is 3.55:1 (APCA Lc −65 passes).
 */
const WAIVERS: Partial<Record<ThemeName, Role[]>> = { dark_signal: ['mute', 'on-red'] }

// ── generated files ────────────────────────────────────────────────────────────────────────────────

const q = (s: string) => `'${s}'`
const obj = (o: Record<string, string | number>) => (Object.keys(o).length ? `{ ${Object.entries(o).map(([k, v]) => `${/^[a-z]\w*$/i.test(k) ? k : q(k)}: ${typeof v === 'number' ? v : q(v)}`).join(', ')} }` : '{}')

function emitTable(themes: Theme[]): string {
  return [
    `/** Every role of the ${themes.length} themes (scheme × accent; docs/LAYOUT-THEME-PLAN.md §4). ${GEN} */`,
    `import type { Roles } from './accents'`, `import type { ThemeName } from './names'`, '',
    'export const THEME_TABLE: Record<ThemeName, Roles> = {',
    ...themes.map(t => `  ${t.name}: ${obj(t.roles)},`), '}', '',
  ].join('\n')
}

/** Engine tokens of a theme from its roles (on top of `dot480` / `PAPER`). */
export const engineOf = (r: Record<Role, string>): Partial<ThemeTokens> => ({
  bg: r.bg, surface: r.surface, surfaceRaised: r.raised, hairline: r.line,
  dotIdle: r['dot-idle'], dotMid: r['dot-mid'], dotFaint: r['dot-faint'], value: r.value,
  dotActive: r.red, dotActiveDim: r['red-dim'],
})
/** The CSS variable each engine token is read from at runtime (`themeTokens()` in src/site/theme/theme.ts). */
export const ENGINE_VARS: Record<string, Role> = { bg: 'bg', surface: 'surface', surfaceRaised: 'raised', hairline: 'line', dotIdle: 'dot-idle', dotMid: 'dot-mid', dotFaint: 'dot-faint', value: 'value', dotActive: 'red', dotActiveDim: 'red-dim' }
/** The untinted scheme base (dark = today's site; light = the paper preset), neutral roles only. */
const schemeBase = (s: Scheme) => neutralRoles(NEUTRALS[s], s)
/** `PAPER`: the untinted paper neutrals with light_signal's accent (light_signal's own surfaces lean red). */
function paperOf(themes: Theme[]): ThemeTokens {
  const ls = themes.find(t => t.name === 'light_signal')!.roles
  return { ...dot480, ...engineOf({ ...ls, ...schemeBase('light') }) } as ThemeTokens
}

function emitDots(themes: Theme[]): string {
  const paper = paperOf(themes)
  const diff = (t: Theme) => {
    const base: ThemeTokens = t.scheme === 'dark' ? dot480 : paper, e = engineOf(t.roles), out: Record<string, string> = {}
    for (const [k, v] of Object.entries(e)) if (!sameColour(v as string, base[k as keyof ThemeTokens] as string)) out[k] = v as string
    return out
  }
  const { gridPx, cornerRadiusCard, ...p } = paper
  return [
    `/** Engine tokens per theme for \`themeTokens()\` (docs/LAYOUT-THEME-PLAN.md §4 Runtime path, step 3). ${GEN} */`,
    `import type { ThemeTokens } from '../../engine/types'`, `import type { ThemeName } from './names'`, '',
    '/** The light neutral preset: warm paper (#f7f7f4-like) with dark ink dots, the light signal red as accent. */',
    `export const PAPER: ThemeTokens = ${obj({ ...p as Record<string, string>, gridPx, cornerRadiusCard })}`, '',
    '/** What each theme changes on its scheme\'s preset (`dot480` dark, `PAPER` light); `dark_signal` changes nothing. */',
    'export const DOT_TABLE: Record<ThemeName, Partial<ThemeTokens>> = {',
    ...themes.map(t => `  ${t.name}: ${obj(diff(t))},`), '}', '',
  ].join('\n')
}

function emitCss(themes: Theme[]): string {
  const ALL = [...NEUTRAL_ROLES, ...DOT_ROLES] as Role[]
  const decl = (r: Partial<Record<Role, string>>, keys: Role[]) => keys.filter(k => r[k] !== undefined).map(k => `  --${k}: ${r[k]};`)
  const out = [
    `/* Theme roles per [data-scheme] × [data-accent] (docs/LAYOUT-THEME-PLAN.md §4). ${GEN}`,
    '   Imported by src/index.css right after src/tokens.css (same specificity as its :root, so the order matters).',
    '   The attributes sit on <html> (set before first paint by the boot script in index.html) or on a subtree that',
    '   pins a theme (a dark inset on a light page): a scope sets BOTH attributes, and its descendants inherit.',
    '   The chrome materials built from these roles (--hair-x, --glow, --glass, ...) are re-declared on every',
    '   [data-scheme] in src/tokens.css, so a scope draws its own lines and glow.',
    '   `--red` is {colors.dotActive}: the accent of the theme, whatever its hue. `--red-halo` is for chrome halos',
    '   only (glow, focus and live ring, swatch ring): never dots, text or lines. */',
  ]
  for (const s of SCHEMES) {
    const sel = s === 'dark' ? ':where(:root), [data-scheme="dark"]' : '[data-scheme="light"]'
    out.push(`${sel} {`, `  color-scheme: ${s};`, ...decl(schemeBase(s), ALL), '}')
  }
  for (const t of themes) {
    const sb: Partial<Record<Role, string>> = schemeBase(t.scheme)
    const sel = [`[data-scheme="${t.scheme}"][data-accent="${t.accent}"]`, ...(t.name === 'dark_signal' ? [':where(:root)'] : [])].join(', ')
    const neutral = ALL.filter(k => t.roles[k] !== sb[k])
    out.push(`${sel} {`, ...decl(t.roles, neutral), ...decl(t.roles, [...ACCENT_ROLES]), '}')
  }
  out.push(
    '::selection { background: var(--selection); }',
    '.no-transition, .no-transition *, .no-transition *::before, .no-transition *::after { transition: none !important; }', '',
  )
  return out.join('\n')
}

const bootHash = () => `'sha256-${createHash('sha256').update(BOOT_SCRIPT, 'utf8').digest('base64')}'`
function withBoot(html: string): string {
  const block = `${BOOT_START}\n    ${bootTag()}\n    ${BOOT_END}`
  if (html.includes(BOOT_START)) return html.replace(new RegExp(`${BOOT_START}[\\s\\S]*?${BOOT_END}`), () => block)
  // right after the viewport meta: before any stylesheet, long before <body>
  return html.replace(/(<meta name="viewport"[^>]*>\n)/, (m) => `${m}    <!-- no-flash theme boot: src/site/theme/boot.ts (written by scripts/site/theme.ts --write; its sha256 is in vercel.json's CSP) -->\n    ${block}\n`)
}
function withCsp(json: string): string {
  return json.replace(/script-src 'self'(?: 'sha256-[A-Za-z0-9+/=]+')*/, () => `script-src 'self' ${bootHash()}`)
}

// ── colour helpers ─────────────────────────────────────────────────────────────────────────────────

/** Opaque hex of a role value (rgba composited over `bg`); undefined for gradients. */
function solidOf(v: string, bg: string): string | undefined {
  if (v.startsWith('#')) return v
  const m = /^rgba\((\d+), (\d+), (\d+), ([\d.]+)\)$/.exec(v)
  if (!m) return undefined
  const [r, g, b, a] = m.slice(1).map(Number), [br, bgg, bb] = hexToRgb(bg).map(c => c * 255)
  return '#' + [r * a + br * (1 - a), g * a + bgg * (1 - a), b * a + bb * (1 - a)].map(c => Math.round(c).toString(16).padStart(2, '0')).join('').toUpperCase()
}
/** Same colour regardless of notation (`#ff3b30` / `rgba(255,59,48,0.6)` / `rgba(255, 59, 48, .6)`). */
function sameColour(a: string, b: string): boolean {
  const norm = (s: string) => {
    if (s.startsWith('#')) return hexToRgb(s).map(c => Math.round(c * 255)).join(',') + ',1'
    const m = /^rgba?\(([^)]*)\)$/.exec(s.replace(/\s+/g, ''))
    return m ? m[1].split(',').map(Number).map((x, i) => (i < 3 ? x : +x.toFixed(3))).concat(m[1].split(',').length === 3 ? [1] : []).join(',') : s
  }
  return norm(a) === norm(b)
}
const fmt = (x: number, d = 2) => x.toFixed(d)

// ── checks ─────────────────────────────────────────────────────────────────────────────────────────

export async function themeChecks(assert: Assert, { print = false } = {}): Promise<void> {
  gamutMisses.length = 0
  const themes = generateAll()
  assert('theme: 7 accents × 2 schemes = 14 themes, named scheme_accent', themes.length === 14 && new Set(themes.map(t => t.name)).size === 14 && ACCENTS.length === 7)
  assert('theme: gamut — every generated colour (ramps, roles, tinted neutrals) is inside sRGB before rounding', gamutMisses.length === 0, gamutMisses.slice(0, 3).map(c => `L ${fmt(c.L, 3)} C ${fmt(c.C, 3)} h ${fmt(c.h, 0)}`).join('; '))
  const bad = themes.flatMap(t => Object.entries(t.roles).filter(([k, v]) => k !== 'red-halo' && !solidOf(v, t.roles.bg)).map(([k]) => `${t.name}.${k}`))
  assert('theme: every colour role is a valid sRGB hex or rgba()', !bad.length, bad.join(', '))

  const waived = (t: Theme, r: Role) => WAIVERS[t.name]?.includes(r) ?? false
  const SURF = ['bg', 'panel', 'surface', 'raised'] as const, TEXT = ['value', 'label', 'mute', 'red-text'] as const
  const textFail: string[] = [], waivedNotes: string[] = []
  for (const t of themes) {
    const r = t.roles
    const pairs: [Role, string, string][] = [
      ...TEXT.flatMap(k => SURF.map(s => [k, r[k], r[s]] as [Role, string, string])),
      ['on-red', r['on-red'], r.red], ['red-surface-text', r['red-surface-text'], r['red-surface']],
    ]
    for (const [k, fg, bg] of pairs) {
      const c = wcag(fg, bg)
      if (c >= 4.5) continue
      if (waived(t, k)) waivedNotes.push(`${t.name}.${k} ${fmt(c)}:1`); else textFail.push(`${t.name}.${k} ${fmt(c)}:1`)
    }
  }
  assert('theme: WCAG ≥ 4.5:1 — value / label / mute and red-text on bg / panel / surface / raised, on-red on red, red-surface-text on red-surface', !textFail.length, textFail.join(', ') || `waived (today's dark_signal, lifted in T6): ${[...new Set(waivedNotes)].join(', ')}`)
  const lcFail = themes.filter(t => Math.abs(apca(t.roles['red-text'], t.roles.surface)) < 60).map(t => `${t.name} Lc ${fmt(apca(t.roles['red-text'], t.roles.surface), 0)}`)
  assert('theme: APCA |Lc| ≥ 60 for red-text on surface (12–14 px chrome)', !lcFail.length, lcFail.join(', '))
  const dotFail = themes.flatMap(t => (['surface', 'bg'] as const).flatMap(s => (['red', 'red-line'] as const).filter(k => wcag(t.roles[k], t.roles[s]) < 3).map(k => `${t.name}.${k}/${s} ${fmt(wcag(t.roles[k], t.roles[s]))}`)))
  assert('theme: WCAG ≥ 3:1 for the accent dots (red) and red-line (borders, focus ring) on surface and bg (1.4.11)', !dotFail.length, dotFail.join(', '))

  const orderFail = themes.filter(t => {
    const lc = (k: Role) => Math.abs(apca(t.roles[k], t.roles.surface)), r = (['dot-faint', 'dot-mid', 'dot-idle', 'value'] as const).map(lc)
    return !(r[0] < r[1] && r[1] < r[2] && r[2] < r[3] && lc('red-dim') < lc('red'))
  }).map(t => t.name)
  assert('theme: APCA order of the dot tones on surface — faint < mid < idle < value, red-dim < red', !orderFail.length, orderFail.join(', '))

  // colour-blind safety: the risk is accent vs grey, so the accent must differ by lightness or by a clear ΔE, not hue alone
  const cvdRows: string[] = [], cvdFail: string[] = []
  for (const t of themes) {
    const r = t.roles, d = distinctness(r.red, [r.value, r['dot-idle'], r['dot-mid']])
    const g = d.grey === r.value ? 'value' : d.grey === r['dot-idle'] ? 'idle' : 'mid', row = `${t.name} vs ${g} (${d.vision}): ΔL ${fmt(d.dL, 3)} ΔE ${fmt(d.dE, 3)}`
    cvdRows.push(row)
    if (d.score < 1) cvdFail.push(row)
  }
  assert(`theme: accent distinct from value / idle / mid grey under normal, protan, deutan and tritan vision (ΔL ≥ ${CVD_DL} or ΔE_OK ≥ ${CVD_DE})`, !cvdFail.length, cvdFail.join('; '))

  // dark_signal is today's site
  const ds = themes.find(t => t.name === 'dark_signal')!, today = todayRoles()
  const drift = Object.entries(today).filter(([k, v]) => !(k in ds.roles) || !sameColour(ds.roles[k as Role], v!)).map(([k, v]) => `${k} ${ds.roles[k as Role] ?? '(no such role)'} ≠ ${v}`)
  const eng = engineOf(ds.roles), engDrift = Object.entries(eng).filter(([k, v]) => !sameColour(v as string, dot480[k as keyof ThemeTokens] as string)).map(([k]) => k)
  assert(`theme: dark_signal equals the ${Object.keys(today).length} colour roles of src/tokens.css :root and its engine tokens equal dot480`, Object.keys(today).length >= 17 && !drift.length && !engDrift.length, [...drift, ...engDrift].join(', '))
  assert('theme: dark_signal is untinted (neutrals = the dark base exactly)', NEUTRAL_ROLES.every(k => ds.roles[k] === schemeBase('dark')[k]) && ds.roles.panel === DARK.panel)
  const pinDrift = Object.entries(PINS).flatMap(([n, p]) => Object.entries(p!).filter(([k, v]) => themes.find(t => t.name === n)!.roles[k as Role] !== v).map(([k]) => `${n}.${k}`))
  assert('theme: hand-pinned values win (dark_signal, dark_vite, light_vite)', !pinDrift.length && themes.find(t => t.name === 'dark_vite')!.roles.red === '#B39AFF' && themes.find(t => t.name === 'light_vite')!.roles.red === '#6C3BFF', pinDrift.join(', '))
  const hues = ACCENTS.map(a => ACCENT_SPECS[a].hue).sort((a, b) => a - b), gaps = hues.map((h, i) => ((hues[(i + 1) % hues.length] - h) + 360) % 360)
  assert('theme: preset hues ≥ 25° apart (tellable at dot size)', Math.min(...gaps) >= 25, gaps.map(g => fmt(g, 0)).join(', '))

  // generated files current; themes.css wired; boot script in index.html; CSP hash
  const want = { [FILES.table]: emitTable(themes), [FILES.dots]: emitDots(themes), [FILES.css]: emitCss(themes) }
  const stale = Object.entries(want).filter(([f, s]) => !existsSync(f) || readFileSync(f, 'utf8').replace(/\r\n/g, '\n') !== s).map(([f]) => f)
  assert('theme: table.ts, dots.ts and themes.css are current (npx tsx scripts/site/theme.ts --write)', !stale.length, stale.join(', '))
  const index = readFileSync('src/index.css', 'utf8'), iTok = index.indexOf('./tokens.css'), iTheme = index.indexOf('./site/theme/themes.css')
  assert('theme: src/index.css imports themes.css after tokens.css (equal specificity: the later wins)', iTok > 0 && iTheme > iTok)
  const css = want[FILES.css], missing = Object.values(ENGINE_VARS).filter(v => !css.includes(`--${v}:`))
  assert('theme: themes.css declares every CSS variable themeTokens() reads (engine tokens come from the CSS at runtime)', !missing.length, missing.join(', '))
  const tokCss = readFileSync(FILES.tokens, 'utf8')
  assert('theme: the chrome materials (--hair-x, --glow, --glass, …) are re-declared on every [data-scheme] (src/tokens.css)', /:root,\s*\[data-scheme\]\s*\{[^}]*--hair-x[^}]*--glow:[^}]*--glass:/.test(tokCss))
  const html = readFileSync(FILES.html, 'utf8'), csp = readFileSync(FILES.vercel, 'utf8')
  assert('theme: index.html carries the boot script exactly once, in <head>, after the color-scheme and theme-color metas it rewrites', html.split(bootTag()).length === 2 && html.indexOf(bootTag()) < html.indexOf('</head>') && html.indexOf('name="theme-color"') < html.indexOf(bootTag()) && html.indexOf('name="color-scheme"') < html.indexOf(bootTag()))
  assert(`theme: vercel.json script-src has the boot script's sha256 (${bootHash()})`, csp.includes(`script-src 'self' ${bootHash()}`))
  if (existsSync(FILES.dist)) assert('theme: dist/index.html kept the boot script byte for byte (the CSP hash holds after vite build)', readFileSync(FILES.dist, 'utf8').includes(bootTag()))
  assert(`theme: boot script ≤ 900 B (${BOOT_SCRIPT.length} B, ${(await gz(BOOT_SCRIPT))} B gz)`, BOOT_SCRIPT.length <= 900)

  // the boot script and the store resolve the same theme
  const { resolvePrefs, resolveScheme, themeTokens } = await import('../../src/site/theme/theme')
  const searches = ['', '?scheme=light', '?scheme=dark', '?accent=vite', '?theme=light_cobalt', '?theme=system_amber', '?theme=bogus_cobalt', '?theme=light_bogus', '?theme=dark_vite&accent=cyan', '?scheme=system&theme=light_amber', '?scheme=nope&accent=nope', '?accent=custom']
  const stored = [null, '{"scheme":"dark","accent":"vite"}', '{"scheme":"light"}', '{"accent":"magenta"}', '{"scheme":"system","accent":"phosphor"}', 'garbage', '"light_cobalt"', '{"accent":"custom"}', 'null', '5']
  const BG = { dark: NEUTRALS.dark.bg, light: NEUTRALS.light.bg }
  const mismatch: string[] = []
  for (const s of searches) for (const st of stored) for (const light of [false, true]) {
    const b = runBoot(s, st, light), p = resolvePrefs(s, st), scheme = resolveScheme(p.scheme, light)
    const want = { 'data-scheme': scheme, 'data-accent': p.accent, 'color-scheme': scheme, 'theme-color': BG[scheme] }
    if (JSON.stringify(b) !== JSON.stringify(want)) mismatch.push(`${s || '(none)'} + ${st} + ${light ? 'light' : 'dark'} OS: boot ${JSON.stringify(b)} vs store ${JSON.stringify(want)}`)
  }
  assert(`theme: boot script ≡ store resolution (${searches.length * stored.length * 2} cases: URL, storage, OS scheme; attributes, color-scheme and theme-color metas)`, !mismatch.length, mismatch.slice(0, 3).join('; '))
  assert('theme: defaults are system + signal; system follows the OS', runBoot('', null, false)['data-scheme'] === 'dark' && runBoot('', null, true)['data-scheme'] === 'light' && runBoot('', null, true)['data-accent'] === 'signal')
  const blocked = runBoot('', null, false, true)
  assert('theme: a blocked localStorage still boots (defaults)', blocked['data-scheme'] === 'dark' && blocked['data-accent'] === 'signal')

  // engine tokens (the browser probe, scripts/site/theme-boot.ts, checks the runtime themeTokens() against tokensOf() in every theme)
  const { tokensOf } = await import('../../src/site/theme/tokens')
  assert("theme: themeTokens() / tokensOf() give dot480 itself for dark_signal (today's cards, same cache keys); without a DOM themeTokens() is dot480", themeTokens() === dot480 && themeTokens('dark', 'signal') === dot480 && tokensOf('dark', 'signal') === dot480)
  const tokFail = themes.filter(t => {
    const k = tokensOf(t.scheme, t.accent), e = engineOf(t.roles)
    return k !== tokensOf(t.scheme, t.accent) || Object.entries(e).some(([key, v]) => !sameColour(k[key as keyof ThemeTokens] as string, v as string)) || k.gridPx !== 4
  }).map(t => t.name)
  assert('theme: tokensOf(scheme, accent) matches the role table for all 14 themes and is memoised', !tokFail.length, tokFail.join(', '))

  if (print) {
    console.log('\n  theme          red      hover    text     line     dim      on-red   solid C (req → got)  min text  dot/surface')
    for (const t of themes) {
      const r = t.roles, minText = Math.min(...TEXT.filter(k => !waived(t, k)).flatMap(k => SURF.map(s => wcag(r[k], r[s]))))
      const clamp = t.pinned.includes('red') ? 'pinned' : `${fmt(t.solid.requestedC, 3)} → ${fmt(t.solid.C, 3)}${t.solid.C < t.solid.requestedC - 1e-3 ? ` (−${fmt(100 * (1 - t.solid.C / t.solid.requestedC), 0)}%)` : ''}`
      console.log(`  ${t.name.padEnd(14)} ${r.red}  ${r['red-hover']}  ${r['red-text']}  ${r['red-line']}  ${r['red-dim']}  ${r['on-red']}  ${clamp.padEnd(20)} ${fmt(minText)}:1    ${fmt(wcag(r.red, r.surface))}:1`)
    }
    for (const row of cvdRows) console.log(`  cvd ${row}`)
  }
}

const gz = async (s: string) => (await import('node:zlib')).gzipSync(s, { level: 9 }).length

/** Run the inline boot script against a fake page; returns the attributes it set on <html> and the metas' content. */
function runBoot(search: string, stored: string | null, prefersLight: boolean, blockStorage = false): Record<string, string> {
  const attrs: Record<string, string> = {}
  const meta = (name: string) => ({ set content(v: string) { attrs[name] = v } })
  const metas: Record<string, object> = { 'meta[name=color-scheme]': meta('color-scheme'), 'meta[name=theme-color]': meta('theme-color') }
  const env = {
    document: { documentElement: { setAttribute: (k: string, v: string) => { attrs[k] = v } }, querySelector: (q: string) => metas[q] ?? null },
    location: { search },
    localStorage: { getItem: () => { if (blockStorage) throw new Error('SecurityError'); return stored } },
    matchMedia: (query: string) => ({ matches: prefersLight && query === '(prefers-color-scheme: light)' }),
    URLSearchParams,
  }
  // oxlint-disable-next-line no-new-func -- evaluating the exact inline script text is the point
  new Function(...Object.keys(env), BOOT_SCRIPT)(...Object.values(env))
  return attrs
}

export function writeThemeFiles(): string[] {
  const themes = generateAll(), wrote: string[] = []
  const put = (f: string, s: string) => { const old = existsSync(f) ? readFileSync(f, 'utf8') : ''; if (old !== s) { writeFileSync(f, s); wrote.push(f) } }
  put(FILES.table, emitTable(themes)); put(FILES.dots, emitDots(themes)); put(FILES.css, emitCss(themes))
  put(FILES.html, withBoot(readFileSync(FILES.html, 'utf8'))); put(FILES.vercel, withCsp(readFileSync(FILES.vercel, 'utf8')))
  return wrote
}

const self = process.argv[1]?.replace(/\\/g, '/')
if (self && import.meta.url.endsWith(self.split('/').slice(-3).join('/'))) {
  if (process.argv.includes('--write')) { const w = writeThemeFiles(); console.log(w.length ? `wrote ${w.join(', ')}` : 'theme files already current') }
  let failures = 0
  await themeChecks((name, cond, detail = '') => { if (!cond) failures++; console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`) }, { print: !process.argv.includes('--check') })
  if (failures) process.exit(1)
}
